        && !in_array((string)($model['role'] ?? 'desk'), ['dect_handset','dect_radio','dect_manager'], true)
    ));
    $sourceSiteKey = trim((string)($tpl['phonebook_source_site'] ?? ''));
    $sourceSiteId = $sourceSiteKey === '' ? $siteId : null;
    foreach ($sites as $candidate) { if ($sourceSiteKey !== '' && (string)($candidate['site_key'] ?? '') === $sourceSiteKey) { $sourceSiteId = (int)$candidate['id']; break; } }
    try { $publishedBooks = $sourceSiteId === null ? [] : $ucm->getPublishedDirectoryPhonebooks($sourceSiteId); $phonebooks = (array)($publishedBooks['phonebooks'] ?? []); }
    catch (\Throwable $e) { $phonebooks = $sourceSiteId === $ucm->localSiteId() ? $ucm->getDirectoryPhonebooks() : []; }
    $buttons = json_decode((string)($tpl['buttons'] ?? '[]'), true) ?: [];
    $settings = json_decode((string)($tpl['setting_overrides'] ?? '{}'), true) ?: [];
    $templateSecretKeys = ['cisco_phone_password','cisco_ssh_password','cisco_admin_password','phone_password','admin_password','user_password'];
    $storedSecrets = [];
    foreach ($templateSecretKeys as $secretKey) {
        if (array_key_exists($secretKey, $settings) && (string)$settings[$secretKey] !== '') { $storedSecrets[$secretKey] = true; }
        unset($settings[$secretKey]);
    }
    $targetModel = trim((string)($tpl['target_model'] ?? ''));
    $targetSeries = strtolower(trim((string)($tpl['target_series'] ?? '')));
    $targetRole = strtolower(trim((string)($tpl['target_role'] ?? '')));
    $seriesOptions = \FreePBX\modules\Ucmprovisioner\ModelCatalog::templateScopeOptions($models);
    $roleOptions = [];
    foreach ($models as $catalogModel) {
        $role = strtolower((string)($catalogModel['role'] ?? 'desk'));
        $roleOptions[$role] = str_replace('_', ' ', $role);
    }
    if ($targetRole !== '' && !isset($roleOptions[$targetRole])) { $roleOptions[$targetRole] = $targetRole . ' — currently unavailable'; }
    if ($targetSeries !== '' && !isset($seriesOptions[$targetSeries])) { $seriesOptions[$targetSeries] = ['family'=>$family,'kind'=>'unavailable','label'=>$targetSeries . ' — currently unavailable','models'=>[]]; }
    ksort($roleOptions);
    // An unrestricted template still remembers the model used to design its canvas. This is
    // editor metadata only; target_model remains the sole assignment restriction.
    $previewModel = $targetModel !== '' ? $targetModel : trim((string)($settings['_design_model'] ?? ''));
    $previewAvailable = false;
    foreach ($models as $catalogModel) { if (strcasecmp($previewModel, $catalogModel['vendor'] . '|' . $catalogModel['model']) === 0) { $previewAvailable = true; break; } }
    [$previewVendor, $previewName] = array_pad(explode('|', $previewModel, 2), 2, '');
    $phonebookKey = (string)($tpl['phonebook_key'] ?? '');
    $phonebookAvailable = in_array($phonebookKey, ['', '__default__', '__none__'], true) || in_array($phonebookKey, array_column($phonebooks, 'book_key'), true);
    $softkeySource = json_decode((string)($tpl['softkeys'] ?? '{}'), true);
    if (!is_array($softkeySource)) { $softkeySource = []; }
    $softkeyWasLegacy = !\FreePBX\modules\Ucmprovisioner\SoftkeyPolicy::isV2($softkeySource)
        && $softkeySource !== [];
    $softkeyLoadError = '';
    try {
        $softkeyPolicy = \FreePBX\modules\Ucmprovisioner\SoftkeyPolicy::isV2($softkeySource)
            ? \FreePBX\modules\Ucmprovisioner\SoftkeyPolicy::normalizeV2($softkeySource)
            : \FreePBX\modules\Ucmprovisioner\SoftkeyPolicy::migrateLegacy($softkeySource);
    } catch (\Throwable $e) {
        $softkeyLoadError = $e->getMessage();
        $softkeyPolicy = [
            'schema'=>2,
            'states'=>[],
            'definitions'=>[],
            'annotations'=>[],
            'unresolved'=>[],
        ];
    }
    $featurePolicy = json_decode((string)($tpl['feature_policy'] ?? '{}'), true) ?: [];
    $softkeyStates = array_keys(\FreePBX\modules\Ucmprovisioner\SoftkeyPolicy::STATE_COMPATIBILITY);
    $softkeyBuiltins = \FreePBX\modules\Ucmprovisioner\SoftkeyPolicy::BUILTIN_DEFINITIONS;
    $softkeyCompatibility = \FreePBX\modules\Ucmprovisioner\SoftkeyPolicy::STATE_COMPATIBILITY;
    $softkeyRecommended = \FreePBX\modules\Ucmprovisioner\SoftkeyPolicy::RECOMMENDED_KEYS;
    $softkeyRequired = \FreePBX\modules\Ucmprovisioner\SoftkeyPolicy::REQUIRED_KEYS;
    $softkeyDocumentedStates = \FreePBX\modules\Ucmprovisioner\SoftkeyPolicy::DOCUMENTED_STATES;
    $softkeyStateDescriptions = \FreePBX\modules\Ucmprovisioner\SoftkeyPolicy::STATE_DESCRIPTIONS;
    $softkeyKeyDescriptions = \FreePBX\modules\Ucmprovisioner\SoftkeyPolicy::KEY_DESCRIPTIONS;
    $featurePolicyKeys = \FreePBX\modules\Ucmprovisioner\TemplateEngine::FEATURE_POLICY_KEYS;
    $siteDefaults = [];
    try { $siteDefaults[$siteId] = (new \FreePBX\modules\Ucmprovisioner\TemplateEngine($ucm))->effectiveSettings($siteId); }
    catch (\Throwable $e) { $siteDefaults[$siteId] = []; }
    $advancedSettings = $settings;
    unset($advancedSettings['_design_model']);
    $advancedSettingsJson = \FreePBX\modules\Ucmprovisioner::browserJson(
        (object)$advancedSettings,
        JSON_PRETTY_PRINT | JSON_UNESCAPED_SLASHES
    );
    $h = fn($v) => htmlspecialchars((string)$v, ENT_QUOTES, 'UTF-8');
?>
