  function isGhp63x(){return family()==='grandstream'&&/^GHP63[01]W?$/.test(String(model().data('model')||''));}
  function keyFeatureSet(){return isGhp63x()?ghpFeatureSet:(featureSets[family()]||{});}
  function expansion(){var f=family(),count=0,size=parseInt(model().data('expkeys')||0,10),max=parseInt(model().data('maxmodules')||0,10);if(f==='cisco_xml'){count=parseInt($('.ucm-setting[data-key=cisco_kem_count]').val()||0,10);var sizes={'7914':14,'7915':24,'7916':24,'BEKEM':36,'CP-8800-Audio':28,'CP-8800-Video':28,'CKEM':36};size=sizes[$('.ucm-setting[data-key=cisco_kem_type]').val()]||0;}else if(f==='yealink'){count=parseInt($('.ucm-setting[data-key=yealink_expansion_count]').val()||0,10);if(!size)size=60;}else if(f==='grandstream'){count=parseInt($('.ucm-setting[data-key=grandstream_expansion_count]').val()||0,10);if(!size)size=40;}return {count:Math.max(0,Math.min(max||3,count)),size:size};}
  function capacity(){var base=parseInt(model().data('keys')||1,10),e=expansion();if(isGhp63x())base=7;return {base:Math.max(1,base),total:Math.max(1,base)+e.count*e.size,exp:e};}
  function options(items,selected,cls){var s=$('<select class="form-control input-sm">').addClass(cls||'');$.each(items,function(v,l){s.append($('<option>').val(v).text(l).prop('selected',String(v)===String(selected)));});if(selected!==undefined&&selected!==null&&!Object.prototype.hasOwnProperty.call(items,String(selected)))s.append($('<option>').val(selected).text('Unavailable in this preview: '+selected).prop('selected',true));return s;}
  function selectSavedValue(select,value){
    var values=Array.isArray(value)?value:[value];
    if(select.is('select'))values.forEach(function(item){var text=String(item==null?'':item);if(!select.find('option').filter(function(){return String($(this).val())===text;}).length)select.append($('<option>').val(text).text(text+' — currently unavailable'));});
    return select.val(value);
  }
  function siteSelect(selected){var s=$('<select class="form-control input-sm ucm-key-site">').append($('<option>').val('').text('Local site'));sites.forEach(function(x){s.append($('<option>').val(x.id).text(x.name).prop('selected',String(x.id)===String(selected)));});return selectSavedValue(s,String(selected||''));}
