  function phonebookSourceSiteId(){var source=$('#ucm-phonebook-source');return source.val()?(source.find('option:selected').data('site-id')||null):$('[name=site_id]').val();}
  function updatePhonebookMode(){var key=String($('#ucm-phonebook-key').val()||''),special=key==='__none__'||key==='__default__';$('#ucm-phonebook-source,[name=phonebook_filename]').prop('disabled',special);if(special){$('#ucm-phonebook-source').val('');$('[name=phonebook_filename]').val('');}}
  function loadPhonebooks(){var current=catalogRead('phonebooks',function(){return JSON.stringify([$('[name=site_id]').val(),$('#ucm-phonebook-source').val()]);});var select=$('#ucm-phonebook-key'),saved=String(select.val()||select.data('saved')||''),status=$('#ucm-phonebook-source-status'),source=phonebookSourceSiteId();if(source===null){status.addClass('text-danger').text('The saved phonebook source is unavailable. Its selection and phonebook policy were preserved.');select.prop('disabled',false);return;}select.data('saved','').prop('disabled',true);status.removeClass('text-danger text-success').text('Loading the published catalog from that PBX…');window.ucmpAjax({data:{command:'phonebooks',site_id:source}}).done(function(resp){if(!current())return;var result=(resp&&resp.result)||{},rows=result.phonebooks||[];select.empty().append($('<option>').val('').text('Inherit / default published phonebook'),$('<option>').val('__default__').text('Use this site’s default phonebook'),$('<option>').val('__none__').text('No phonebook — omit directory URLs'));rows.forEach(function(book){select.append($('<option>').val(book.book_key).text(String(book.name||book.book_key)+' — '+String(book.filename||'')+(book.is_default?' (default)':'')+' · '+String(book.contacts||0)+' contacts'));});if(saved&&!select.find('option').filter(function(){return $(this).val()===saved;}).length)select.append($('<option>').val(saved).text(saved+' — currently unavailable on this source'));select.val(saved);status.toggleClass('text-danger',!result.ok).toggleClass('text-success',!!result.ok).text(result.message||rows.length+' published phonebook(s) loaded.');}).fail(function(){if(!current())return;status.addClass('text-danger').text('Could not query this site’s phonebook catalog. The current selection was preserved.');}).always(function(){if(!current())return;select.prop('disabled',false);updatePhonebookMode();});}
  function wireKeyPicker(target,site,label){var listId='ucm-key-extensions-'+(++pickerSeq),list=$('<datalist>').attr('id',listId);target.attr({'list':listId,'placeholder':'Choose or type an extension'}).after(list);label.attr('placeholder','Blank = automatic label policy');var sequence=0;function refresh(){var request=++sequence;loadExtensions(site.val(),function(rows){if(request!==sequence)return;list.empty();rows.forEach(function(row){var ext=String(row.extension||row.ext||row.id||''),name=String(row.description||row.name||row.display_name||row.label||'');if(ext)list.append($('<option>').val(ext).attr('label',name).text(name));});});}site.on('change',refresh);refresh();}
