    list:function(rows){jobs=rows.filter(function(job){return Number(job.source_site_id)===sourceSite&&((job.scopes||[]).indexOf('templates')!==-1);});var select=$('#ucm-template-sync-job').empty().append($('<option value="0">').text('New sync job'));jobs.forEach(function(job){select.append($('<option>').val(job.id).text(job.name));});}
  });
  function wirePicker(root){var $root=$(root),$items=$root.find('.ucm-picker-item'),$filter=$root.find('.ucm-picker-filter');function refresh(){var query=String($filter.val()||'').toLowerCase(),visible=0,total=$items.length;$items.each(function(){var $item=$(this),match=!query||$item.text().toLowerCase().indexOf(query)!==-1;$item.prop('hidden',!match);if(match)visible++;});var selected=$items.find('input:checked').length;$root.find('.ucm-picker-count').text(selected+' selected · '+visible+' visible of '+total);} $filter.on('input',refresh);$root.on('ucm-picker-refresh',refresh);$root.find('.ucm-picker-visible').on('click',function(){$items.filter(function(){return !$(this).prop('hidden');}).find('input').prop('checked',true).trigger('change');});$root.find('.ucm-picker-all').on('click',function(){$items.find('input').prop('checked',true).trigger('change');});$root.find('.ucm-picker-clear').on('click',function(){$items.find('input').prop('checked',false).trigger('change');});$items.find('input').on('change',refresh);refresh();}
  $('.ucm-picker').each(function(){wirePicker(this);});function refreshPickers(){$('.ucm-picker').trigger('ucm-picker-refresh');}
  function selectedIds(){return $('.ucm-template-sync-select:checked').map(function(){return Number(this.value);}).get();}
  function selectionSummary(){var ids=selectedIds(),names=[];ids.forEach(function(id){names.push($.trim($('[data-template-id="'+id+'"] .tp2-template-name strong').first().text()));});$('#ucm-template-sync-selection').text(ids.length?ids.length+' selected: '+names.join(', '):'None selected');}
  function scheduleVisibility(){var mode=$('#ucm-template-sync-mode').val();$('.ucm-template-sync-interval').prop('hidden',mode!=='interval');$('.ucm-template-sync-clock').prop('hidden',mode==='interval');$('.ucm-template-sync-weekdays').prop('hidden',mode!=='weekly');}
  function openDrawer(){selectionSummary();$('#ucm-template-sync-drawer').prop('hidden',false)[0].scrollIntoView({behavior:'smooth',block:'start'});}
  function feedback(message,bad){$('#ucm-template-sync-feedback').toggleClass('text-danger',!!bad).toggleClass('text-success',!bad).text(message||'');}
  function renderItems(job){var items=(job&&job.items)||[],$box=$('#ucm-template-sync-items').empty();if(!items.length)return;$box.append($('<h4>').text('Destination state'));items.forEach(function(item){var detail=item.pause_reason||'',missing=item.missing||{};if(Object.keys(missing).length)detail=Object.keys(missing).map(function(k){return k+': '+missing[k];}).join('; ');var $row=$('<div class="tp2-sync-item">').append($('<strong>').text('Site #'+item.target_site_id+' · '+item.object_key),$('<span class="tp2-badge">').text(item.status),$('<small>').text(detail));if(item.status==='paused')$row.append($('<button type="button" class="btn btn-xs btn-default">').text('Resume').on('click',function(){syncEditor.mutate({command:'configurationsync',op:'resume',id:job.id,target_site_id:item.target_site_id,object_type:item.object_type,object_key:item.object_key});}));$box.append($row);});}
  function loadJob(job,preserveResult){if(syncEditor.busy())return;if(!preserveResult)syncEditor.showResult(job&&job.last_result||{});currentJob=job||null;$('#ucm-template-sync-job').val(job?job.id:0);$('#ucm-template-sync-name').val(job?job.name:('Template push from Site #'+sourceSite));$('.ucm-template-sync-target').prop('checked',false);(job&&job.target_site_ids||[]).forEach(function(id){$('.ucm-template-sync-target[value="'+id+'"]').prop('checked',true);});$('.ucm-template-sync-select').prop('checked',false);(job&&job.template_ids||[]).forEach(function(id){$('.ucm-template-sync-select[value="'+id+'"]').prop('checked',true);});$('#ucm-template-sync-enabled').prop('checked',job?(job.enabled===true||Number(job.enabled)===1):false);$('#ucm-template-sync-lock').prop('checked',job?(job.soft_lock===true||Number(job.soft_lock)===1):true);$('#ucm-template-sync-retry').prop('checked',job?(job.retry_unreachable===true||Number(job.retry_unreachable)===1):true);var s=job&&job.schedule||{};$('#ucm-template-sync-mode').val(s.mode||'interval');$('#ucm-template-sync-minutes').val(s.interval_minutes||job&&job.interval_minutes||60);$('#ucm-template-sync-time').val(s.time||'02:00');$('.ucm-template-sync-weekday').prop('checked',false);(s.weekdays||[1,2,3,4,5]).forEach(function(day){$('.ucm-template-sync-weekday[value="'+day+'"]').prop('checked',true);});$('#ucm-template-sync-delete').prop('disabled',!job);scheduleVisibility();selectionSummary();refreshPickers();renderItems(job);}
  function payload(){return {command:'configurationsync',op:'save',id:currentJob?currentJob.id:0,name:$('#ucm-template-sync-name').val(),source_site_id:sourceSite,enabled:$('#ucm-template-sync-enabled').is(':checked')?1:0,soft_lock:$('#ucm-template-sync-lock').is(':checked')?1:0,retry_unreachable:$('#ucm-template-sync-retry').is(':checked')?1:0,target_site_ids:window.ucmpRetainedSelection('.ucm-template-sync-target',currentJob&&currentJob.target_site_ids).map(Number),scopes:['templates'],template_ids:window.ucmpRetainedSelection('.ucm-template-sync-select',currentJob&&currentJob.template_ids).map(Number),schedule_mode:$('#ucm-template-sync-mode').val(),interval_minutes:Number($('#ucm-template-sync-minutes').val()||60),schedule_time:$('#ucm-template-sync-time').val(),schedule_weekdays:$('.ucm-template-sync-weekday:checked').map(function(){return Number(this.value);}).get()};}

  function save(thenRun){var p=payload();if(!p.template_ids.length){feedback('Select at least one template.',true);return;}syncEditor.save(p,thenRun);}

  $('#ucm-template-filter').on('input',function(){var query=String($(this).val()||'').toLowerCase(),shown=0;$('[data-template-row]').each(function(){var visible=!query||$(this).text().toLowerCase().indexOf(query)!==-1;$(this).toggle(visible);if(visible)shown++;});$('#ucm-template-no-results').prop('hidden',shown!==0||!query);});
  $('#ucm-template-select-all').on('change',function(){$('[data-template-row]:visible .ucm-template-sync-select').prop('checked',this.checked);selectionSummary();});$('.ucm-template-sync-select').on('change',selectionSummary);
  $('#ucm-template-sync-open').on('click',openDrawer);$('#ucm-template-sync-close').on('click',function(){$('#ucm-template-sync-drawer').prop('hidden',true);});$('.ucm-template-sync-one').on('click',function(){loadJob(null);$('.ucm-template-sync-select').prop('checked',false);$('.ucm-template-sync-select[value="'+$(this).data('id')+'"]').prop('checked',true);openDrawer();});
  $('#ucm-template-sync-job').on('change',function(){var id=Number(this.value||0);loadJob(jobs.find(function(job){return Number(job.id)===id;})||null);});$('#ucm-template-sync-mode').on('change',scheduleVisibility);$('#ucm-template-sync-save').on('click',function(){save(false);});$('#ucm-template-sync-run').on('click',function(){save(true);});$('#ucm-template-sync-delete').on('click',function(){if(!currentJob||!window.confirm('Delete this template sync job? Destination content is preserved.'))return;syncEditor.mutate({command:'configurationsync',op:'delete',id:currentJob.id});});
  loadJob(null);
});</script>
